script:
(function () {
  'use strict';
  // Interest with contributions, tax on interest and inflation. Month-by-month simulation:
  // interest accrues at the effective monthly rate implied by the compounding choice,
  //   i = (1 + r/n)^(n/12) - 1   (continuous: i = e^(r/12) - 1),
  // monthly contributions land each month and the yearly contribution once a year (start or end).
  // Tax: each year's interest x tax rate is paid out of the balance at the end of that year (and at
  // the end of a final part-year). Today's dollars = balance / (1 + inflation)^(months/12).
  // Checked in Node (five.test.js): $20,000 + $5,000 a year at 5% compounded annually for 5 years,
  // end-of-year deposits = $53,153.79 (20000 x 1.05^5 + 5000 x (1.05^5 - 1)/0.05); start-of-year
  // deposits = $54,535.20; $10,000 at 5% annually, 1 year, 25% tax = $10,375.00; $10,000 at 6%
  // monthly for 10 years = $18,193.97 (1.005^120); $10,000 at 5% continuous for 1 year = $10,512.71
  // (e^0.05); $10,000 for 10 years at 3% inflation = $7,440.94 in today's dollars (1.03^-10).
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var OUTPUTS = ['itEnd', 'itDeposited', 'itNet', 'itGross', 'itTaxPaid', 'itReal', 'itLost', 'itApy', 'itRealRate'];

  // --- calc start
  function monthlyRate(rate, n) {
    if (n === 0) return Math.exp(rate / 12) - 1;
    return Math.pow(1 + rate / n, n / 12) - 1;
  }

  function simulate(o) {
    var i = monthlyRate(o.rate, o.comp), bal = o.principal, deposited = o.principal,
        gross = 0, tax = 0, rows = [], yDep = 0, yInt = 0;
    for (var m = 1; m <= o.months; m++) {
      var add = 0, g;
      if (o.begin) { add = o.monthly + ((m - 1) % 12 === 0 ? o.annual : 0); bal += add; }
      g = bal * i; bal += g;
      if (!o.begin) { add = o.monthly + (m % 12 === 0 ? o.annual : 0); bal += add; }
      deposited += add; yDep += add; yInt += g; gross += g;
      if (m % 12 === 0 || m === o.months) {
        var t = yInt > 0 ? yInt * o.tax : 0;
        bal -= t; tax += t;
        rows.push({ year: Math.ceil(m / 12), part: m % 12 !== 0, dep: yDep, int: yInt, tax: t, bal: bal,
                    real: bal / Math.pow(1 + o.inflation, m / 12) });
        yDep = 0; yInt = 0;
      }
    }
    return { balance: bal, deposited: deposited, gross: gross, tax: tax, rows: rows,
             real: bal / Math.pow(1 + o.inflation, o.months / 12), apy: Math.pow(1 + i, 12) - 1 };
  }
  // --- calc end

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }

  function pct(x) { return (x * 100).toFixed(3).replace(/\.?0+$/, '') + '%'; }

  function fail(msg) {
    var error = document.getElementById('itError');
    error.hidden = false;
    error.textContent = msg;
    OUTPUTS.forEach(function (id) { document.getElementById(id).textContent = '–'; });
    document.getElementById('itSchedule').innerHTML = '';
    document.getElementById('itNote').hidden = true;
  }

  function update() {
    var principal = num('itPrincipal'), annual = num('itAnnual'), monthly = num('itMonthly'),
        rate = num('itRate'), years = num('itYears'), extra = num('itMonths'), tax = num('itTax'),
        infl = num('itInflation');
    var comp = parseInt(document.getElementById('itCompound').value, 10);
    var begin = document.getElementById('itTiming').value === 'begin';
    document.getElementById('itError').hidden = true;
    if ([principal, annual, monthly, rate, years, extra, tax, infl].some(isNaN)) return fail('Fill in every field with a number (use 0 where it does not apply).');
    if (principal < 0 || annual < 0 || monthly < 0) return fail('Deposits and contributions cannot be negative.');
    if (rate < 0 || rate > 100) return fail('Enter an interest rate from 0 to 100%.');
    if (years < 0 || years > 100 || extra < 0 || extra > 11 || years !== Math.floor(years) || extra !== Math.floor(extra)) return fail('Enter whole years from 0 to 100 and 0 to 11 extra months.');
    if (years * 12 + extra < 1) return fail('Enter a length of at least one month.');
    if (tax < 0 || tax > 100) return fail('Enter a tax rate from 0 to 100%.');
    if (infl < 0 || infl > 50) return fail('Enter an inflation rate from 0 to 50%.');

    var r = simulate({ principal: principal, annual: annual, monthly: monthly, rate: rate / 100, comp: comp,
                       months: years * 12 + extra, tax: tax / 100, inflation: infl / 100, begin: begin });
    if (!isFinite(r.balance) || Math.abs(r.balance) > 1e15) return fail('That result is too large to show. Try smaller numbers.');
    document.getElementById('itEnd').textContent = money.format(r.balance);
    document.getElementById('itDeposited').textContent = money.format(r.deposited);
    document.getElementById('itNet').textContent = money.format(r.gross - r.tax);
    document.getElementById('itGross').textContent = money.format(r.gross);
    document.getElementById('itTaxPaid').textContent = money.format(r.tax);
    document.getElementById('itReal').textContent = money.format(r.real);
    document.getElementById('itLost').textContent = money.format(r.balance - r.real);
    document.getElementById('itApy').textContent = pct(r.apy);
    var realRate = (1 + r.apy * (1 - tax / 100)) / (1 + infl / 100) - 1;
    document.getElementById('itRealRate').textContent = pct(realRate);
    var note = document.getElementById('itNote');
    note.hidden = realRate >= 0;
    note.textContent = 'After tax, this rate does not keep up with inflation, so the money loses buying power each year.';
    document.getElementById('itSchedule').innerHTML = r.rows.map(function (row) {
      return '<tr><td>' + row.year + (row.part ? ' (part)' : '') + '</td><td>' + money.format(row.dep) + '</td><td>' +
             money.format(row.int) + '</td><td>' + money.format(row.tax) + '</td><td>' + money.format(row.bal) +
             '</td><td>' + money.format(row.real) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('itForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
